/// shift-roster: Read only, one person at a time, with a week toolbar
private struct ShiftRosterExample1: View {
    @State private var week = 0
    @State private var view = MonarchCalendarToolbarView.week
    private var from: Date { Date(timeIntervalSinceReferenceDate: 815_875_200 + Double(week) * 7 * 86_400) }

    var body: some View {
        VStack(alignment: .leading) {
            MonarchCalendarToolbar(
                "Week \(week + 1)",
                view: $view,
                views: [.week],
                onToday: { week = 0 },
                onPrevious: { week -= 1 },
                onNext: { week += 1 }
            )
            MonarchShiftRoster(
                members: [MonarchShiftRosterMember(id: "a", name: "Alex Kim")],
                shifts: [MonarchShiftRosterShift(id: "e", name: "Evening", start: 14 * 60, end: 22 * 60)],
                from: from,
                value: .constant(["a": [from: .shift("e")]]),
                days: 3,
                layout: .byPerson,
                isReadOnly: true,
                today: nil
            )
        }
    }
}

/// team-calendar: Month with a toolbar
private struct TeamCalendarExample0: View {
    @State private var view = MonarchCalendarToolbarView.month
    private var calendar: Calendar {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: "UTC") ?? .gmt
        calendar.firstWeekday = 2
        return calendar
    }
    private func hex(_ value: String) -> Color {
        let number = UInt32(value.drop(while: { $0 == "#" }), radix: 16) ?? 0
        return Color(
            red: Double((number >> 16) & 0xFF) / 255,
            green: Double((number >> 8) & 0xFF) / 255,
            blue: Double(number & 0xFF) / 255
        )
    }

    var body: some View {
        VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
            MonarchCalendarToolbar(
                "November 2026",
                view: $view,
                views: [.month],
                labels: MonarchCalendarToolbarLabels(today: "Today"),
                onToday: {},
                onPrevious: {},
                onNext: {}
            )
            MonarchTeamCalendar(
                members: [
                    MonarchTeamCalendarMember("Alex Kim", id: "a", description: "Design"),
                    MonarchTeamCalendarMember("Sam Lee", id: "b", description: "Engineering"),
                    MonarchTeamCalendarMember("Priya Nair", id: "c", description: "Engineering"),
                    MonarchTeamCalendarMember("Jordan Park", id: "d", description: "Support"),
                ],
                entries: [
                    MonarchTeamCalendarEntry("Annual leave", id: "1", memberID: "a", start: Date(timeIntervalSince1970: 1_794_182_400), end: Date(timeIntervalSince1970: 1_794_528_000), color: hex("#2f7d6d")),
                    MonarchTeamCalendarEntry("Sick leave", id: "2", memberID: "b", start: Date(timeIntervalSince1970: 1_793_750_400), color: hex("#b54a3a"), portion: .firstHalf),
                    MonarchTeamCalendarEntry("Annual leave", id: "3", memberID: "c", start: Date(timeIntervalSince1970: 1_794_960_000), end: Date(timeIntervalSince1970: 1_795_132_800), color: hex("#2f7d6d"), isPending: true),
                    MonarchTeamCalendarEntry("Away", id: "4", memberID: "d", start: Date(timeIntervalSince1970: 1_795_564_800), end: Date(timeIntervalSince1970: 1_795_651_200)),
                ],
                month: Date(timeIntervalSince1970: 1_793_491_200),
                holidays: [MonarchTeamCalendarHoliday("Company holiday", date: Date(timeIntervalSince1970: 1_794_355_200))],
                today: Date(timeIntervalSince1970: 1_793_750_400),
                calendar: calendar
            )
            .environment(\.locale, Locale(identifier: "en-GB"))
        }
    }
}

